SELECT * FROM agent_schedules
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
ORDER BY status ASC, next_run_at ASC NULLS LAST, updated_at DESC, id DESC

SELECT * FROM agent_schedules
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND id = #{id}

SELECT COUNT(*) FROM agent_schedules
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND status IN ('active', 'paused')

mapper.delete:
DELETE FROM agent_schedules
WHERE organization_id = #{organizationId}
  AND user_id = #{userId}
  AND id = #{id}

mapper.update:
UPDATE agent_schedule_runs
SET conversation_id = #{conversationId},
    user_message_id = #{userMessageId},
    status = #{status},
    error = #{error}
WHERE id = #{id}

mapper.select:
SELECT * FROM agent_schedule_runs
WHERE organization_id = #{organizationId}
  AND schedule_id = #{scheduleId}
ORDER BY claimed_at DESC, id DESC
LIMIT #{limit}

SELECT EXISTS (
  SELECT 1 FROM agent_schedule_runs
  WHERE schedule_id = #{scheduleId}
    AND id <> #{currentRunId}
    AND status = 'started'
    AND user_message_id IS NULL
    AND claimed_at > now() - interval '10 minutes'
)

