UPDATE agent_schedules
SET consecutive_failures = 0,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE agent_schedules
SET status = #{status},
    consecutive_failures = #{consecutiveFailures},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}
